# ДЗ 02 — Калькулятор в обратной польской нотации

**Статус:** в работе

**RPN (Reverse Polish Notation)** — обратная польская нотация, в которой оператор записывается после операндов. Например, выражению $(10-3)\cdot 2$ соответствует `10 3 - 2 *`.

Калькулятор использует упакованные целые числа типа `value` и арифметические функции из первой части задания (NaN-boxing).

> [!example]- Исходный код — `src/main.c`
> ```c
> /*
>  * Part 2: reverse Polish notation calculator.
>  *
>  * TODO: implement the calculator. Requirements and examples are in README.md.
>  * Every .c file in src/ (including nanbox.c) is linked into one program, so
>  * you may split the code into as many files as you like; exactly one of them
>  * must define main().
>  */
> #include <stdio.h>
> #include <ctype.h>
> #include "nanbox.h"
> #include <stdlib.h>
> #include <errno.h>
> #include <stdint.h>
> #include <inttypes.h>
> 
> typedef struct {
>         value *data;
>         size_t size;
>         size_t capacity;
>     } Stack;
> 
> typedef struct {
>     char *data;
>     size_t len;
>     size_t capacity;
> } Token;
> 
> int push(Stack *s, value v) {
>     if (s->size >= s->capacity || s->capacity == 0) {
>         value *ptr = NULL;
>         if (s->capacity != 0) {
>             ptr = realloc(s->data, 2 * sizeof(value) * s->capacity);
>             if (ptr != NULL) {
>                 s->capacity = s->capacity*2;
>                 s->data = ptr;
>             }
>             else {
>                 return 6;
>             }
>         }
>         else {
>             ptr = realloc(s->data, 2 * sizeof(value));
>             if (ptr != NULL) {
>                 s->capacity = 2;
>                 s->data = ptr;
>             }
>             else {
>                 return 6;
>             }
>         }
>     }
>     s->data[s->size] = v;
>     s->size++;
>     return 0;
> }
> 
> int pop(Stack *s, value *out) {
>     if (s->size == 0) {
>         return 2;
>     }
>     *out = s->data[s->size-1];
>     s->size--;
>     return 0;
> }
> 
> int token_append(Token *t, char c) {
>     if (t->capacity == 0 || t->len >= t->capacity-1) {
>         char *ptr = NULL;
>         if (t->capacity != 0) {
>             ptr = realloc(t->data, t->capacity * 2 * sizeof(char));
>             if (ptr != NULL) {
>                 t->data = ptr;
>                 t->capacity = t->capacity*2;
>             }
>             else {
>                 return 6;
>             }
>         }
>         else {
>             ptr = realloc(t->data, 2*sizeof(char));
>             if (ptr != NULL) {
>                 t->data = ptr;
>                 t->capacity = 2;
>             }
>             else {
>                 return 6;
>             }
>         }
>     }
>     t->data[t->len] = c;
>     t->len++;
>     return 0;
> }
> 
> int is_operator(const char *token) {
>     if ((token[0] == '-' || token[0] == '+' || token[0] == '*' || token[0] == '/') && (token[1] == '\0')) {
>         return 1;
>     }
>     else {
>         return 0;
>     }
> }
> 
> int is_number(const char *token) {
>     size_t start = 0;
> 
>     if (token[0] == '-') {
>        start = 1;
>     }
> 
>     if (token[start] == '\0') {
>         return 0;
>     }
> 
>     while (token[start] != '\0') {
>         if (!isdigit(token[start])) {
>             return 0;
>         }
>         start++;
>     }
>     return 1;
> }
> 
> int parse_number(const char *token, int32_t *out) {
>     if (!is_number(token)) {
>         return 1;
>     }
> 
>     errno = 0;
>     long num = strtol(token, NULL, 10);
> 
>     if (errno == ERANGE || num < INT32_MIN || num > INT32_MAX) {
>         return 1;
>     }
> 
>     *out = (int32_t)num;
>    
>     return 0;
> }
> 
> int process_token(Stack *s, const char *token) {
>     if (is_operator(token)) {
>         if (s->size < 2) {
>             return 2;
>         }
>         value op1;
>         value op2;
>         pop(s, &op2);
>         pop(s, &op1);
>         value result;
>         int status = 0;
>         switch (token[0]) {
>             case '+':
>                 status = v_add(op1, op2, &result);
>                 break;
>             case '-':
>                 status = v_sub(op1, op2, &result);
>                 break;
>             case '*':
>                 status = v_mul(op1, op2, &result);
>                 break;
>             case '/':
>                 status = v_div(op1, op2, &result);
>                 break;
>         }
>         if (status == 2) {
>             return 4;
>         }
>         if (status == 3) {
>             return 3;
>         }
>         return push(s, result);
>     }
>     else {
>         int32_t result;
>         if (parse_number(token, &result) != 0) {
>             return 1;
>         }
>         value num = box_int(result);
>         return push(s, num);
>     }
> }
> 
> int main(void) {
>     Stack stack = {NULL, 0, 0};
>     Token token = {NULL, 0, 0};
>     int c;
>     int status = 0;
> 
>     while ((c = getchar()) != EOF) {
> 
>         if (isspace(c)) {
>             if (token.len != 0) {
>                 status = token_append(&token, '\0');
>                 if (status != 0) {
>                     break;
>                 }
>                 status = process_token(&stack, token.data);
>                 if (status != 0) {
>                     break;
>                 }
>                 token.len = 0;
>             }
>         }
>         else {
>             status = token_append(&token, c);
>             if (status != 0) {
>                 break;
>             }
>         }
>     }
>     if (status == 0 && token.len != 0) {
>         status = token_append(&token, '\0');
>         
>         if (status == 0) {
>             status = process_token(&stack, token.data); 
>         }
>     }
>     
>     if (status == 0 && stack.size != 1) {
>         status = 5;
>     }
>     if (status == 0) {
>         printf("%d\n", unbox_int(stack.data[0]));
>     }
> 
>     free(stack.data);
>     free(token.data);
>     return status;
> }
> ```

## 1. Общая архитектура

![](assets/dz-02/rpn-architecture.svg)

Программа читает стандартный ввод посимвольно, собирает символы в токены и обрабатывает их слева направо.

- **Число** — преобразуется в `int32_t`, упаковывается через `box_int` и помещается в стек.
- **Оператор** — извлекает два числа из стека, выполняет операцию и помещает результат обратно.

После окончания ввода в стеке должно остаться ровно одно число — результат выражения.

Для реализации используются два динамических массива:

| Поле | `Stack` | `Token` |
| --- | --- | --- |
| `data` | Указатель `value *` на упакованные числа | Указатель `char *` на символы текущего токена |
| Текущий размер | `size` — количество элементов | `len` — количество записанных символов |
| `capacity` | Вместимость в элементах `value` | Вместимость в символах `char` |

Обе структуры изначально имеют состояние `{NULL, 0, 0}`: память ещё не выделена, размер и вместимость равны нулю.

## 2. Динамический стек: `push` и `pop`

![](assets/dz-02/rpn-stack.svg)

### `push`

Функция `push(Stack *s, value v)` добавляет упакованное число в конец массива.

Если свободных ячеек нет, вместимость увеличивается вдвое. При первом добавлении выделяется память под два элемента. Размер выделяемой памяти вычисляется в байтах: `2 * sizeof(value) * s->capacity`.

`realloc(NULL, n)` работает аналогично `malloc(n)`. Результат `realloc` сохраняется во временный указатель `ptr`: при неудаче исходный указатель `s->data` остаётся доступным для последующего освобождения памяти. Поля `data` и `capacity` обновляются только при успешном выделении.

После этого значение записывается в `s->data[s->size]`, а `size` увеличивается на единицу.

### `pop`

Функция `pop(Stack *s, value *out)` извлекает последний элемент массива. Если стек пуст, возвращается код ошибки `2`.

В противном случае значение `s->data[s->size - 1]` записывается по указателю `out`, после чего `size` уменьшается на единицу. Физически элемент не удаляется, а выделенная память сохраняется для дальнейших добавлений.

Например, при извлечении из стека `[10, 20, 30]` в `*out` записывается `30`, логический размер становится равным двум, а `capacity` не меняется.

> [!note] Результат и статус
> `pop` возвращает код завершения через `return`, а извлечённое значение — через выходной параметр `out`. Такой подход позволяет одновременно передать результат операции и сообщить об ошибке.

## 3. Сборка токена: `token_append`

Функция `token_append(Token *t, char c)` устроена аналогично `push`, но работает с массивом символов.

Условие `t->capacity == 0 || t->len >= t->capacity - 1` учитывает необходимость места под завершающий нулевой символ. При отсутствии места массив расширяется через `realloc`.

Символ записывается в `t->data[t->len]`, затем `len` увеличивается. Завершающий символ `\0` добавляется отдельно при достижении границы токена или конца ввода. До этого буфер не обязан быть полноценной C-строкой.

Например, при чтении `-52 ` буфер последовательно принимает состояния:

| Прочитанный символ | Записанные символы |
| --- | --- |
| `-` | `['-']` |
| `5` | `['-', '5']` |
| `2` | `['-', '5', '2']` |
| Пробел | `['-', '5', '2', '\0']` |

После обработки токена выполняется `token.len = 0`. Память не освобождается: следующий токен записывается в тот же буфер с начала.

## 4. Распознавание токенов

### `is_operator`

Токен считается оператором, если его первый символ — один из `+`, `-`, `*`, `/`, а второй — `\0`. Таким образом, одиночный `-` является оператором, но `-5` — нет.

### `is_number`

Проверяет **формат**, а не числовое значение токена:

- Начальный минус пропускается, если присутствует.
- После необязательного минуса должна находиться хотя бы одна цифра.
- Все оставшиеся символы до `\0` проверяются через `isdigit`.

`isdigit` возвращает ненулевое значение для цифры и ноль в противном случае. Поэтому используется проверка `!isdigit(...)`.

### `parse_number`

После проверки формата строка преобразуется в число:

`long num = strtol(token, NULL, 10);`

`strtol` (String to Long — преобразование строки в `long`) использует десятичное основание. Перед вызовом `errno` сбрасывается в ноль.

Необходимы две отдельные проверки диапазона:

- `errno == ERANGE` — ошибка диапазона при преобразовании строки в `long`.
- `num < INT32_MIN || num > INT32_MAX` — число не помещается в `int32_t`.

Например, на платформе с 64-битным `long` число `3000000000` помещается в `long`, но превышает `INT32_MAX` (2147483647). Поэтому одной проверки `errno` недостаточно.

При успехе результат записывается в `*out` с приведением к `int32_t`, а функция возвращает `0`. Некорректный формат или выход за диапазон приводит к возврату `1`.

## 5. Обработка токена: `process_token`

Связь между буфером и вычислениями устанавливается вызовом `process_token(&stack, token.data)`.

> [!important] Передача массива
> Поле `token.data` содержит указатель на первый символ буфера. Параметр `const char *token` функции `process_token` получает копию этого указателя, а не копию всего массива. Поэтому `token[0]` и следующие элементы внутри функции обращаются к той же памяти, в которой был собран токен. `const` запрещает изменять символы через этот указатель.

Если токен является числом, `parse_number` получает его значение, `box_int` упаковывает его, а `push` помещает в стек.

Если токен является оператором, сначала проверяется наличие двух элементов. Затем выполняются `pop(s, &op2)` и `pop(s, &op1)`.

**Правый операнд извлекается первым**, поскольку он был помещён в стек последним. Например, для `10 3 -` необходимо вычислить `10 - 3`, а не `3 - 10`.

Оператор выбирается через `switch (token[0])`. Функции `v_add`, `v_sub`, `v_mul`, `v_div` выполняют операции над упакованными значениями и записывают результат в выходной параметр `result`.

Код переполнения первой части `2` преобразуется в код второй части `4`. Код деления на ноль `3` сохраняется.

Выражение `return push(s, result);` возвращает не только успешный статус, но и возможную ошибку выделения памяти, не теряя её при передаче результата в `main`.

## 6. Главная функция: `main`

![](assets/dz-02/rpn-main.svg)

### Чтение ввода

`getchar()` возвращает очередной символ как `int` либо `EOF` (End of File — конец файла). Тип `int` позволяет отличить значение `EOF` от прочитанных символов.

В цикле `while ((c = getchar()) != EOF)` возможны два сценария:

- Если символ не является пробельным, он добавляется в буфер через `token_append`.
- Если `isspace(c)` возвращает ненулевое значение и буфер непустой, в конец токена добавляется `\0`, вызывается `process_token`, затем `token.len` обнуляется.

Последовательные пробельные символы пропускаются, если буфер пуст. После каждой потенциально неуспешной операции проверяется `status`. При ошибке выполняется `break`.

### Обработка последнего токена

Если ввод заканчивается без пробела, последний токен остаётся в буфере необработанным. Поэтому после цикла проверяется `status == 0 && token.len != 0`.

При отсутствии ошибок добавляется `\0`, и только после успешного добавления вызывается `process_token`.

Проверка `status == 0` принципиальна: цикл мог завершиться не только из-за `EOF`, но и из-за ошибки. Продолжение обработки в таком случае нарушило бы требование остановиться на первой ошибке.

### Завершение

Если ошибок нет, проверяется итоговый размер стека. При `stack.size != 1` устанавливается `status = 5`.

При успехе единственное значение распаковывается через `unbox_int(stack.data[0])` и выводится с переводом строки. В исходнике используется `%d`, соответствующий `int32_t` на рассматриваемой платформе. Для переносимого вывода `int32_t` также существует макрос `PRId32` из `<inttypes.h>`.

Независимо от результата освобождаются оба динамических массива через `free`, после чего возвращается `status`.

Именно поэтому при ошибках внутри цикла используется `break`, а не немедленный `return`: необходимо дойти до общего освобождения памяти.

